ALTER TABLE chat_outbox DROP CONSTRAINT chat_outbox_event_type_check;
ALTER TABLE chat_outbox ADD CONSTRAINT chat_outbox_event_type_check CHECK(event_type IN ('message.persisted','login.succeeded','login.failed','logout.succeeded','keyword.rust','keyword.ownership','keyword.borrow','keyword.lifetime','keyword.async','keyword.trait','keyword.sql','keyword.postgresql','keyword.leptos','keyword.tauri'));
CREATE TABLE chat_topic_consent(user_id UUID NOT NULL REFERENCES chat_users(id),room_id VARCHAR(40) NOT NULL REFERENCES chat_rooms(id),enabled BOOLEAN NOT NULL DEFAULT false,withdraw_before TIMESTAMPTZ,withdraw_pending BOOLEAN NOT NULL DEFAULT false,PRIMARY KEY(user_id,room_id));
CREATE TABLE chat_topic_events(event_id UUID PRIMARY KEY,message_id UUID NOT NULL REFERENCES chat_messages(id),user_id UUID NOT NULL REFERENCES chat_users(id),room_id VARCHAR(40) NOT NULL REFERENCES chat_rooms(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),withdrawal_queued BOOLEAN NOT NULL DEFAULT false,withdrawal_ack BOOLEAN NOT NULL DEFAULT false);
CREATE INDEX chat_topic_events_owner_idx ON chat_topic_events(user_id,room_id,created_at) WHERE NOT withdrawal_ack;
CREATE TABLE chat_topic_withdraw_outbox(id UUID PRIMARY KEY,event_ids UUID[] NOT NULL CHECK(cardinality(event_ids) BETWEEN 1 AND 500),status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','leased','delivered')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),lease_token UUID,lease_until TIMESTAMPTZ);
